pub fn lookup_native_hover(word: &str, qualified: &str) -> Option<&'static str> {
    match qualified {
        "cli.parse" => Some("```conduit\nfunc cli.parse<T>() -> T | CliError\n```\nParses process CLI arguments into `T` (defined via `cli` DSL or `@cli.*` struct annotations)."),
        "cli.parse_args" => Some("```conduit\nfunc cli.parse_args<T>(args: [String]) -> T | CliError\n```\nParses an explicit `[String]` argument list into `T`."),
        "cli.help" => Some("```conduit\nfunc cli.help<T>() -> String\n```\nReturns the formatted `--help` text for CLI schema `T`."),
        "env.load" => Some("```conduit\nfunc env.load<T>() -> T | EnvError\n```\nLoads environment variables into struct `T` using `@env` field annotations and defaults."),
        "env.get" => Some("```conduit\nfunc env.get(name: String) -> String?\n```\nReturns the environment variable value, or `nil` if unset."),
        "env.require" => Some("```conduit\nfunc env.require(name: String) -> String | EnvError\n```\nReturns the environment variable value, or `EnvError` if unset or empty."),
        "env.args" => Some("```conduit\nfunc env.args() -> [String]\n```\nReturns the command-line arguments passed to the process."),
        "json.decode" => Some("```conduit\nfunc json.decode<T>(raw: String) -> T | DecodeError\n```\nDecodes a strict RFC 8259 JSON string into typed struct/list/map `T`."),
        "json.encode" => Some("```conduit\nfunc json.encode<T>(value: T) -> String | EncodeError\n```\nSerializes `value` into a deterministic JSON string."),
        "json.parse" => Some("```conduit\nfunc json.parse(raw: String) -> json.Value | DecodeError\n```\nParses JSON into a dynamic `json.Value` tree."),
        "json.stringify" => Some("```conduit\nfunc json.stringify(val: json.Value) -> String | EncodeError\n```\nSerializes a dynamic `json.Value` into JSON text."),
        "time.now" => Some("```conduit\nfunc time.now() -> Timestamp | TimeError\n```\nReturns the current wall-clock UTC timestamp."),
        "time.monotonic" => Some("```conduit\nfunc time.monotonic() -> Instant\n```\nReturns a monotonic clock instant for elapsed duration measurement."),
        "time.elapsed" => Some("```conduit\nfunc time.elapsed(start: Instant) -> Duration | TimeError\n```\nReturns the elapsed `Duration` since `start`."),
        "time.seconds" => Some("```conduit\nfunc time.seconds(n: Int) -> Duration | TimeError\n```\nCreates a `Duration` of `n` seconds."),
        "time.milliseconds" => Some("```conduit\nfunc time.milliseconds(n: Int) -> Duration | TimeError\n```\nCreates a `Duration` of `n` milliseconds."),
        "validation.check" => Some("```conduit\nfunc validation.check<T>(value: T) -> T | ValidationError\n```\nValidates `value` against all `@validation.*` and custom `[#validator]` field rules."),
        _ => match word {
            "CliError" => Some("`struct CliError { kind: String, message: String }` (`cdt.cli`) — Returned on `--help` (`kind == \"help\"`) or CLI parse errors."),
            "EnvError" => Some("`struct EnvError { name: String, message: String }` (`cdt.env`) — Returned when a required env var is missing or invalid."),
            "ValidationError" => Some("`struct ValidationError { issues: [Issue] }` (`cdt.validation`) — Returned by `validation.check()` when one or more rules fail."),
            "Issue" => Some("`struct Issue { path: String, code: String, message: String }` (`cdt.validation`) — Single validation failure entry."),
            "DecodeError" => Some("`struct DecodeError { message: String }` (`cdt.json`) — Returned when JSON decoding fails."),
            "EncodeError" => Some("`struct EncodeError { message: String }` (`cdt.json`) — Returned when JSON encoding fails."),
            "TimeError" => Some("`struct TimeError { message: String }` (`cdt.time`) — Returned on invalid time/duration operations."),
            "Instant" => Some("Opaque monotonic clock measurement (`cdt.time`)."),
            "Timestamp" => Some("Opaque UTC wall-clock timestamp (`cdt.time`)."),
            "Duration" => Some("Opaque time span (`cdt.time`) with `.nanoseconds()`, `.milliseconds()`, `.seconds()`."),
            _ => None,
        },
    }
}

pub fn lookup_builtin_hover(word: &str) -> Option<&'static str> {
    match word {
        "export" => Some("**export** — Exposes a top-level `func`, `struct`, or `cli` declaration to importing modules."),
        "import" => Some("**import** — Imports symbols from a `cdt.*` module or relative `.cdt` file (`import { a } from \"./mod\"`)."),
        "func" => Some("**func** — Function declaration: `func name(param: Type) -> ReturnType { ... }`"),
        "struct" => Some("**struct** — Record type declaration: `struct Name { field: Type = default }`"),
        "cli" => Some("**cli** — Declarative CLI schema block (`flag`, `opt`, `arg`, `rest`, `cmd`, `group`)."),
        "group" => Some("**group** — Nested command group inside a `cli` block."),
        "cmd" => Some("**cmd** — Subcommand definition inside a `cli` or `group` block."),
        "flag" => Some("**flag** — Boolean CLI flag (`--name`, `-s`) inside a `cli` / `cmd` block."),
        "opt" => Some("**opt** — Named CLI option (`--name val`, `-s val`) inside a `cli` / `cmd` block."),
        "arg" => Some("**arg** — Positional CLI argument inside a `cli` / `cmd` block."),
        "rest" => Some("**rest** — Trailing positional `[String]` arguments inside a `cli` / `cmd` block."),
        "switch" => Some("**switch** — Exhaustive pattern matching over union/error/optional types."),
        "guard" => Some("**guard** — Early exit check: `guard cond else { return ... }`"),
        "print" => Some("`func print(value: Any) -> Void` — Prints a value to stdout."),
        "map" => Some("`list |> map((x: T) => U)` — Transforms each element of a list."),
        "filter" => Some("`list |> filter((x: T) => Bool)` — Keeps elements matching predicate."),
        "reduce" => Some("`func reduce<T, A>(list: [T], init: A, fn: (A, T) -> A) -> A` — Folds a list into a single value."),
        "len" => Some("`.len() -> Int` — Returns the length of a `String`, `[T]`, or `Map<K, V>`."),
        "split" => Some("`String.split(sep: String) -> [String]` — Splits a string by separator."),
        "contains" => Some("`.contains(item) -> Bool` — Checks whether substring or element is present."),
        "starts_with" => Some("`String.starts_with(prefix: String) -> Bool`"),
        "ends_with" => Some("`String.ends_with(suffix: String) -> Bool`"),
        "replace" => Some("`String.replace(from: String, to: String) -> String`"),
        "to_string" => Some("`.to_string() -> String` — Converts value to `String`."),
        "to_int" => Some("`String.to_int() -> Int | ParseError` — Parses a strict integer."),
        "to_float" => Some("`.to_float() -> Float | ParseError` (on `String`) or `Int.to_float() -> Float`."),
        "clamp" => Some("`.clamp(lo, hi)` — Clamps `Int` or `Float` to `[lo, hi]`."),
        "abs" => Some("`.abs()` — Returns absolute value of `Int` or `Float`."),
        _ => None,
    }
}

pub fn module_completions(alias: &str) -> Option<&'static str> {
    match alias {
        "cli" => Some(r#"[{"label":"parse","kind":3,"detail":"cli.parse<T>() -> T | CliError"},{"label":"parse_args","kind":3,"detail":"cli.parse_args<T>(args: [String]) -> T | CliError"},{"label":"help","kind":3,"detail":"cli.help<T>() -> String"},{"label":"CliError","kind":7,"detail":"struct CliError { kind: String, message: String }"}]"#),
        "env" => Some(r#"[{"label":"load","kind":3,"detail":"env.load<T>() -> T | EnvError"},{"label":"get","kind":3,"detail":"env.get(name: String) -> String?"},{"label":"require","kind":3,"detail":"env.require(name: String) -> String | EnvError"},{"label":"args","kind":3,"detail":"env.args() -> [String]"},{"label":"EnvError","kind":7,"detail":"struct EnvError { name: String, message: String }"}]"#),
        "json" => Some(r#"[{"label":"decode","kind":3,"detail":"json.decode<T>(raw: String) -> T | DecodeError"},{"label":"encode","kind":3,"detail":"json.encode<T>(val: T) -> String | EncodeError"},{"label":"parse","kind":3,"detail":"json.parse(raw: String) -> json.Value | DecodeError"},{"label":"stringify","kind":3,"detail":"json.stringify(val: json.Value) -> String | EncodeError"},{"label":"DecodeError","kind":7,"detail":"struct DecodeError"},{"label":"EncodeError","kind":7,"detail":"struct EncodeError"},{"label":"Value","kind":7,"detail":"json.Value"}]"#),
        "time" => Some(r#"[{"label":"now","kind":3,"detail":"time.now() -> Timestamp | TimeError"},{"label":"monotonic","kind":3,"detail":"time.monotonic() -> Instant"},{"label":"elapsed","kind":3,"detail":"time.elapsed(start: Instant) -> Duration | TimeError"},{"label":"seconds","kind":3,"detail":"time.seconds(n: Int) -> Duration | TimeError"},{"label":"milliseconds","kind":3,"detail":"time.milliseconds(n: Int) -> Duration | TimeError"},{"label":"Instant","kind":7,"detail":"time.Instant"},{"label":"Timestamp","kind":7,"detail":"time.Timestamp"},{"label":"Duration","kind":7,"detail":"time.Duration"},{"label":"TimeError","kind":7,"detail":"time.TimeError"}]"#),
        "validation" => Some(r#"[{"label":"check","kind":3,"detail":"validation.check<T>(val: T) -> T | ValidationError"},{"label":"min","kind":3,"detail":"@validation.min(n)"},{"label":"max","kind":3,"detail":"@validation.max(n)"},{"label":"email","kind":3,"detail":"@validation.email"},{"label":"ValidationError","kind":7,"detail":"struct ValidationError { issues: [Issue] }"},{"label":"Issue","kind":7,"detail":"struct Issue"}]"#),
        _ => None,
    }
}

